// Generated by Trae Work
(function () {
  function $all(sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); }
  function $(sel, root) { return (root || document).querySelector(sel); }

  var STORAGE_KEY = 'i_am_here_lang';
  var langToggle = $('#langToggle');
  var LANGS = ['zh', 'en', 'th'];

  function applyLang(lang) {
    LANGS.forEach(function (code) {
      $all('[data-lang="' + code + '"]').forEach(function (el) {
        el.style.display = code === lang ? '' : 'none';
      });
    });
    try { localStorage.setItem(STORAGE_KEY, lang); } catch (e) {}
  }

  function getLang() {
    try {
      var v = localStorage.getItem(STORAGE_KEY);
      if (LANGS.indexOf(v) !== -1) return v;
    } catch (e) {}
    // default: Chinese
    return 'zh';
  }

  function copyText(text) {
    if (!text) return;
    // Prefer async clipboard
    if (navigator.clipboard && navigator.clipboard.writeText) {
      return navigator.clipboard.writeText(text);
    }
    // Fallback
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.setAttribute('readonly', 'readonly');
    ta.style.position = 'fixed';
    ta.style.left = '-9999px';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); } catch (e) {}
    document.body.removeChild(ta);
    return Promise.resolve();
  }

  function flashButton(btn, ok) {
    if (!btn) return;
    var old = btn.textContent;
    btn.textContent = ok ? '已複製' : '失敗';
    btn.style.borderColor = ok ? 'rgba(61,245,255,0.55)' : 'rgba(255,120,120,0.55)';
    setTimeout(function () {
      btn.textContent = old;
      btn.style.borderColor = '';
    }, 900);
  }

  // Init language
  applyLang(getLang());
  if (langToggle) {
    langToggle.addEventListener('click', function () {
      var now = getLang();
      var idx = LANGS.indexOf(now);
      var next = LANGS[(idx + 1) % LANGS.length];
      applyLang(next);
    });
  }

  // Copy buttons
  document.addEventListener('click', function (e) {
    var t = e.target;
    if (!t) return;
    if (t.matches && t.matches('[data-copy]')) {
      var url = t.getAttribute('data-copy');
      copyText(url)
        .then(function () { flashButton(t, true); })
        .catch(function () { flashButton(t, false); });
    }
  });

  // Smooth scroll for internal links
  $all('a[href^="#"]').forEach(function (a) {
    a.addEventListener('click', function (e) {
      var id = a.getAttribute('href');
      if (!id || id === '#') return;
      var target = document.querySelector(id);
      if (!target) return;
      e.preventDefault();
      target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      history.replaceState(null, '', id);
    });
  });
})();
